using Ror2Common;

namespace Samus
{
    // Melee characters' entries in the pause menu's controls window. Every sheet is
    // generated by ror2-common's MeleeSheet from the fighter's own skill layout
    // (the same names and descriptions the loadout and HUD show) plus the generic
    // Melee control scheme; a fighter adds only a subtitle and any inputs unique
    // to it. Pad names match the buttons the native sim reads (MeleePad), not
    // RoR2's rebindable skill slots.
    internal static class MeleeSheets
    {
        public static ControlSheet SamusSheet() => MeleeSheet.Build(
            "Intergalactic Bounty Hunter", Skills.Layout,
            footer: "X is also RoR2's interact: with a prompt up it goes to that, not the grapple.",
            grapple: true,
            grabPad: "Aim the 20 m grapple. Bosses pull Samus to them; other enemies are captured.",
            grabKeys: "Aim the 20 m grapple. Bosses pull Samus to them; other enemies are captured.",
            extras: sheet =>
            {
                sheet.Pad("Captured enemies")
                    .Add("LS + LT / RT", "Throw them")
                    .Add("Neutral LT / RT", "Pummel")
                    .Add("X + LT, or A", "Let go; bosses pull Samus instead");
                sheet.Keys("Captured enemies")
                    .Add("Move + Secondary / Primary", "Throw them")
                    .Add("Secondary / Primary", "Pummel")
                    .Add("Interact + Secondary, or Jump", "Let go; bosses pull Samus instead");
            });

        public static ControlSheet FoxSheet() => MeleeSheet.Build("Leader of Star Fox", Fox.FoxSkills.Layout);
        public static ControlSheet LuigiSheet() => MeleeSheet.Build("The Eternal Understudy", Luigi.LuigiSkills.Layout);
        public static ControlSheet CaptainSheet() => MeleeSheet.Build("F-Zero Racer", Captain.CaptainSkills.Layout);
        public static ControlSheet LinkSheet() => MeleeSheet.Build("Hero of Hyrule", Link.LinkSkills.Layout);
        public static ControlSheet PikachuSheet() => MeleeSheet.Build(
            "The Electric Mouse Pokemon", Pikachu.PikachuSkills.Layout,
            footer: "Quick Attack homes on your lock-on (the enemy nearest your crosshair) and arrives in two zips; turn the stick or press LB again for the second.");
        public static ControlSheet YoshiSheet() => MeleeSheet.Build("Yoshi's Island Dinosaur", Yoshi.YoshiSkills.Layout);
        public static ControlSheet DonkeySheet() => MeleeSheet.Build("King of the Jungle", Donkey.DonkeySkills.Layout);
    }
}
